<?php get_header(); ?>
<header class="gmr-archive-head"><div class="gmr-wrap"><span class="gmr-kicker">Galeria Mayari Rojas</span><h1 class="gmr-page-title">Catalogo</h1><p>Una seleccion viva de pintura, escultura, obra grafica y joyeria.</p><div class="gmr-filters"><?php foreach ( array( 'pintura'=>'Pintura','escultura'=>'Escultura','obra-grafica'=>'Obra grafica','joyeria'=>'Joyeria','sin-disciplina'=>'Otras obras' ) as $slug=>$name ) { $term=get_term_by('slug',$slug,'product_cat'); if($term) printf('<a class="gmr-filter" href="%s">%s</a>',esc_url(get_term_link($term)),esc_html($name)); } ?></div></div></header>
<section class="gmr-section"><div class="gmr-wrap"><?php if ( have_posts() ) { echo '<div class="gmr-grid">'; while ( have_posts() ) { the_post(); get_template_part( 'template-parts/artwork', 'card' ); } echo '</div><nav class="gmr-pagination">'; the_posts_pagination(); echo '</nav>'; } else echo '<p class="gmr-empty">No hay obras disponibles en esta seleccion.</p>'; ?></div></section>
